/**
 * The idle prefetch table (src/i18n/font-prefetch-samples.ts), generated by
 * scripts/fonts/build-font-sheets.mts from the app font sheets: for the
 * Korean, Japanese and Chinese UIs, their family's most frequent shards
 * (Google numbers shards by frequency, highest first) up to the policy caps,
 * each with one character that loads exactly that shard.
 */
import { readFile, stat } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

import { buildFontPrefetchSamples } from '../../../scripts/fonts/build-font-sheets.mts';
import {
  fontCodePoints,
  openFontFile,
  parseFontFaceRules,
  parseUnicodeRange,
} from '../../../scripts/fonts/font-files.mts';
import { APP_FONT_SHEETS } from '../app-font-contract.ts';
import { FONT_PREFETCH_BY_LANGUAGE } from '../font-prefetch-samples.ts';
import { FONT_PREFETCH_MAX_BYTES, FONT_PREFETCH_MAX_FACES } from '../font-loading-policy.ts';
import { LANGUAGE_OPTIONS } from '../locales.ts';

const ROOT = resolve('.');
const SHARD_RE = /\.(\d+)\.woff2$/u;

function shardNumber(file: string): number {
  const match = SHARD_RE.exec(file);
  if (!match?.[1]) throw new Error(`${file} is not a numbered shard`);
  return Number(match[1]);
}

async function sheetFaces(family: string) {
  const sheet = APP_FONT_SHEETS.find((entry) => entry.family === family);
  if (!sheet) throw new Error(`no app sheet for ${family}`);
  const css = await readFile(join(ROOT, sheet.path), 'utf8');
  return parseFontFaceRules(css).map((rule) => ({
    shard: shardNumber(rule.file),
    file: join(ROOT, dirname(sheet.path), rule.url),
    codePoints: parseUnicodeRange(rule.unicodeRange ?? ''),
  }));
}

describe('font prefetch samples', () => {
  it('is the generator output', async () => {
    const generated = await buildFontPrefetchSamples(ROOT);
    expect(generated.path).toBe('src/i18n/font-prefetch-samples.ts');
    expect(await readFile(join(ROOT, generated.path), 'utf8')).toBe(generated.text);
  });

  it.each([
    ['ko', 'Noto Sans KR', 119, 100, 392_712],
    ['ja', 'Noto Sans JP', 119, 100, 394_936],
    ['zh-hans', 'Noto Sans SC', 119, 114, 342_912],
    ['zh-hant', 'Noto Sans TC', 119, 114, 391_444],
  ] as const)(
    'gives the %s UI the %s shards #%i to #%i (%i B)',
    async (code, family, first, last, bytes) => {
      const list = FONT_PREFETCH_BY_LANGUAGE[code];
      expect(list?.family).toBe(family);
      expect(list?.shards.map(({ shard }) => shard)).toEqual(
        Array.from({ length: first - last + 1 }, (_, index) => first - index),
      );
      expect(list?.shards.reduce((sum, shard) => sum + shard.bytes, 0)).toBe(bytes);
    },
  );

  it('gives every other UI nothing', () => {
    expect(Object.keys(FONT_PREFETCH_BY_LANGUAGE).sort()).toEqual([
      'ja',
      'ko',
      'zh-hans',
      'zh-hant',
    ]);
    for (const { code } of LANGUAGE_OPTIONS) {
      if (!['ko', 'ja', 'zh-hans', 'zh-hant'].includes(code)) {
        expect(FONT_PREFETCH_BY_LANGUAGE[code], code).toBeUndefined();
      }
    }
  });

  it('stays within the policy caps, and the next shard would not', async () => {
    for (const [code, list] of Object.entries(FONT_PREFETCH_BY_LANGUAGE)) {
      if (!list) continue;
      const total = list.shards.reduce((sum, shard) => sum + shard.bytes, 0);
      expect(list.shards.length, code).toBeLessThanOrEqual(FONT_PREFETCH_MAX_FACES);
      expect(total, code).toBeLessThanOrEqual(FONT_PREFETCH_MAX_BYTES);
      const faces = await sheetFaces(list.family);
      const next = faces.find(({ shard }) => shard === (list.shards.at(-1)?.shard ?? 0) - 1);
      if (next && list.shards.length < FONT_PREFETCH_MAX_FACES) {
        expect(total + (await stat(next.file)).size, code).toBeGreaterThan(FONT_PREFETCH_MAX_BYTES);
      }
    }
  });

  it("records each shard's place among its family's faces in the sheet", async () => {
    // The runtime reads that face first instead of scanning every face's
    // unicode-range (phase C of src/i18n/locale-fonts.ts).
    for (const [code, list] of Object.entries(FONT_PREFETCH_BY_LANGUAGE)) {
      if (!list) continue;
      const faces = await sheetFaces(list.family);
      for (const shard of list.shards) {
        expect(faces[shard.face]?.shard, `${code} #${shard.shard}`).toBe(shard.shard);
      }
    }
  });

  it('records each shard file size and a sample that only that shard declares and draws', async () => {
    for (const [code, list] of Object.entries(FONT_PREFETCH_BY_LANGUAGE)) {
      if (!list) continue;
      const faces = await sheetFaces(list.family);
      for (const { shard, sample, bytes } of list.shards) {
        const where = `${code} #${shard}`;
        expect([...sample], where).toHaveLength(1);
        const codePoint = sample.codePointAt(0) ?? 0;
        expect(/\p{L}/u.test(sample), where).toBe(true);
        const declaring = faces.filter(({ codePoints }) => codePoints.has(codePoint));
        expect(
          declaring.map((face) => face.shard),
          where,
        ).toEqual([shard]);
        const [face] = declaring;
        if (!face) continue;
        expect((await stat(face.file)).size, where).toBe(bytes);
        expect(fontCodePoints(await openFontFile(face.file)).has(codePoint), where).toBe(true);
      }
    }
  });
});
